import type { SupabaseClient } from "@supabase/supabase-js";

/**
 * Admin client for the Revenue OS tables. `integrations/supabase/types.ts` is
 * generated by Lovable and only knows the wa_* tables until the new migration
 * is applied and types are regenerated, so this returns an untyped client.
 * Once types.ts includes the new tables this can return the typed client.
 */
export async function db(): Promise<SupabaseClient> {
  const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
  return supabaseAdmin as unknown as SupabaseClient;
}

export const APP_URL = () => (process.env["PUBLIC_APP_URL"] ?? "").replace(/\/$/, "");
